pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 betLimit, uint256 openFlag) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(openFlag == 0 || openFlag == 1);
        betLimit = bound(betLimit, 1, 1e18);

        if (openFlag == 1) {
            c.OpenToThePublic();
        }

        c.AdjustBetAmounts(betLimit);

        if (openFlag == 1) {
            vm.deal(player, betLimit);
            vm.prank(player);
            c.wager{value: betLimit}();
        }

        c.AdjustBetAmounts(betLimit);

        bool wagered = c.hasPlayerWagered(player);
        if (openFlag == 1 && wagered) {
            assertTrue(c.currentBetLimit() == betLimit);
        } else {
            assertTrue(true);
        }
    }
}

