pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betLimit) public {
        vm.assume(betLimit > 0 && betLimit <= address(this).balance);
        c.AdjustBetAmounts(betLimit);
        c.OpenToThePublic();
        vm.deal(address(this), 2 * betLimit);
        c.wager{value: betLimit}();
        uint256 balanceBefore = address(c).balance;
        // Play and expect a win (if winning condition met)
        // We cannot force a win, but we can check the invariant after any play
        c.play();
        uint256 balanceAfter = address(c).balance;
        // If the player won, balanceBefore should be 2 * (balanceBefore - balanceAfter)
        // because payout transfers half the balance
        if (balanceBefore > balanceAfter) {
            assertTrue(balanceBefore == 2 * (balanceBefore - balanceAfter));
        } else {
            // If no win, the balance changed only by the loss amount (betLimit/2)
            assertTrue(balanceBefore - balanceAfter == betLimit / 2 || balanceBefore == balanceAfter);
        }
    }
}

