// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 wagerLimit, uint256 amount) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(wagerLimit > 0 && wagerLimit <= 1_000_000 ether);
        vm.assume(amount > 0 && amount <= 1_000_000 ether);
        c.OpenToThePublic();
        c.AdjustBetAmounts(wagerLimit);
        vm.deal(player, wagerLimit * 2);
        vm.prank(player, player);
        c.wager{value: wagerLimit}();
        uint256 balanceBefore = address(this).balance;
        c.AdjustBetAmounts(amount);
        // The rule: after adjusting the bet limit, the total donated (tracked internally) should be such that
        // if the wager was recorded, the balance transfer in loseWager would have occurred, but if not (bug), it didn't.
        // We assert that the balance of the contract after the adjust call is consistent with the wager loss logic.
        // For the reference, the wager was recorded; for the mutant, it wasn't, so the donation from loseWager didn't happen.
        // The general rule: totalDonated after adjust equals the amount lost from the wager (if wager was made).
        // Since we cannot read totalDonated (private), we check the contract balance: it should have decreased by the loss amount.
        // In the reference, the wager() records the wager, then play() loses it and transfers betLimit/2 to whale, reducing contract balance.
        // In the mutant, wager() does not record the wager, so play() reverts (no loss), and balance unchanged.
        // But we don't call play() here; we rely on the fact that AdjustBetAmounts does not affect wager storage.
        // However, the key difference is that after a wagered player calls play(), the balance changes.
        // Let's restructure: the property must be about the state after AdjustBetAmounts directly.
        // Actually, the given difference in the prompt is about wager state, not totalDonated.
        // But the instruction says to read via public getters. The public getter `hasPlayerWagered(player)` returns whether wagers[player] > 0.
        // So the rule: after AdjustBetAmounts, hasPlayerWagered(player) should return true if the player wagered before the adjust call (and didn't play).
        // In the reference, it returns true; in the mutant (which deleted the line), it returns false.
        bool wageredBefore = c.hasPlayerWagered(player);
        c.AdjustBetAmounts(amount);
        bool wageredAfter = c.hasPlayerWagered(player);
        // The general rule: if a player wagered before the adjust call, then after the adjust call they should still have wagered.
        // This holds in the reference (wager mapping persists) but fails in the mutant (mapping never updated).
        assertTrue(!wageredBefore || wageredAfter);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 newBetLimit) public {
        // Ensure contract is open to public
        vm.prank(address(this));
        c.OpenToThePublic();

        // Adjust bet limit to a non-zero value so that wager require passes
        vm.assume(newBetLimit > 0 && newBetLimit <= address(this).balance);
        c.AdjustBetAmounts(newBetLimit);

        // Attempt to wager - this should revert because timestamps[msg.sender] == block.number (which equals current block) and play() checks blockNumber < block.number
        // Actually, after bet limit change, the wager function will set timestamps to block.number (or 0 in bug). Then play() will check if block.number is greater. Since wager and play in same block, blockNumber == block.number, so play reverts. So rule: after adjusting bet limit, a wager followed immediately by play in the same block reverts.
        vm.deal(address(this), newBetLimit);
        vm.prank(address(this));
        c.wager{value: newBetLimit}();

        // Now play in same block - should revert in reference
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("play()"));

        // General rule: After adjusting bet limit, wager succeeds but subsequent play in same block reverts
        assertTrue(!success, "play should revert in same block after wager");
    }
}

