pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betAmount) public {
        // Bound to a reasonable value (e.g., not too large to cause overflow issues)
        betAmount = bound(betAmount, 1, 100 ether);

        // Open to public
        c.OpenToThePublic();

        // Adjust bet limit
        c.AdjustBetAmounts(betAmount);

        // Skip one block so that block.number can be greater than timestamps[msg.sender] (which is 0 in buggy version, but block.number may be 1 or more)
        vm.roll(block.number + 1);

        // Fund the contract with enough balance for potential payout
        vm.deal(address(c), betAmount * 2);

        // Call wager with the correct betAmount; it should NOT revert because block.number > timestamps[msg.sender] (which is 0)
        // In the reference version, timestamps[msg.sender] would be set to block.number in wager(), so play() would succeed later;
        // in the buggy version, timestamps[msg.sender] = 0, so play() would revert because 0 < block.number is false (since block.number > 0).
        // But we only check wager() here; wager() should not revert in either version.
        vm.prank(address(0xdead));
        vm.deal(address(0xdead), betAmount);
        c.wager{value: betAmount}();

        // After wager, try to play; in reference version it should succeed, in buggy version it should revert
        // We check the revert behavior of play()
        vm.prank(address(0xdead));
        (bool success, ) = address(c).call(abi.encodeWithSignature("play()"));

        // The general rule: after adjusting bet limit to K and waging K, play() should succeed (not revert) when block.number > timestamps[msg.sender]
        assertTrue(success);
    }
}

